CONVERSATION_INPUT_CLASS = {
  /** The composer's outer bordered container. */
  wrapper: 'dial-ci-wrapper',
  /** The row holding the textarea, add button, tool chips, and footer actions. */
  actionRow: 'dial-ci-action-row',
  /** The wrapper around the textarea area inside the action row. */
  textareaWrap: 'dial-ci-textarea-wrap',
  /** The wrapper around the add-attachment button. */
  addCluster: 'dial-ci-add-cluster',
  /** The wrapper around the tool chips, present only when tools are shown. */
  toolsChips: 'dial-ci-tools-chips',
  /** The trailing cluster: model selector, mic, and send/stop buttons. */
  footerActions: 'dial-ci-footer-actions',
  /** The model selector trigger button, in every presentation. */
  modelSelectorButton: 'dial-ci-model-selector-button',
  /**
   * The model menu root. Present on all three presentations: the desktop
   * dropdown, the host-supplied `modelPickerOverlay` dropdown, and the mobile
   * bottom sheet.
   */
  modelMenu: 'dial-ci-model-menu',
  /** The sticky search header inside the model menu. */
  modelMenuSearch: 'dial-ci-model-menu-search',
  /** Every deployment row in the model menu. */
  modelMenuItem: 'dial-ci-model-menu-item',
  /**
   * The currently selected deployment row, additive to `modelMenuItem`. The
   * check mark itself is drawn by `@epam/ai-dial-ui-kit`, which marks it
   * `DIAL_KIT_CLASS.menuItemCheck`; this package owns no class for it.
   */
  modelMenuItemSelected: 'dial-ci-model-menu-item-selected',
} as const

BottomSheetShell: FC<BottomSheetShellProps> = ({
  isOpen,
  title,
  closeLabel,
  onClose,
  onBack,
  backLabel,
  'aria-label': ariaLabel,
  style,
  titleClassName = 'dial-body-semi-text',
  className,
  colors,
  children,
}) => {
  /*
   * Focus management (initial focus into the sheet, Tab trapping, and
   * restoration to the trigger on close) lives in the hook and keys off this
   * ref; `tabIndex={-1}` below makes the dialog itself the focus fallback
   * when a sheet hosts no focusable content.
   */
  const sheetRef = useRef<HTMLDivElement | null>(null);
  useBottomSheet(isOpen, onClose, sheetRef);

  if (!isOpen || typeof document === 'undefined') return null;

  const cssVars = buildCssVars({
    '--ci-backdrop': colors?.backdrop,
    '--ci-sheet-bg': colors?.sheetBg,
    '--ci-sheet-text': colors?.sheetText,
    '--ci-sheet-divider': colors?.divider,
  });

  return createPortal(
    <>
      {/* Backdrop — onPointerDown avoids the touch-synthesized ghost click */}
      <div
        className={mergeClasses(styles.backdrop, 'fixed inset-0 z-[55]')}
        style={cssVars}
        onPointerDown={onClose}
        aria-hidden
      />

      {/* Sheet */}
      <div
        ref={sheetRef}
        role="dialog"
        aria-modal
        aria-label={title ?? ariaLabel}
        tabIndex={-1}
        style={{ ...cssVars, ...style }}
        className={mergeClasses(
          styles.sheet,
          'fixed inset-x-0 bottom-0 z-[60] flex max-h-[85dvh] flex-col rounded-t-lg',
          className,
        )}
      >
        {title != null && (
          <>
            {/* Header: optional back on start, title centered, close on end */}
            <div className="relative flex h-[60px] flex-shrink-0 items-center justify-center px-4">
              {onBack && (
                <div className="absolute start-4">
                  <GhostIconButton
                    icon={
                      <IconArrowLeft
                        size={DIAL_ICON_SIZE.LG}
                        stroke={DIAL_KIT_ICON_STROKE}
                        className="rtl:scale-x-[-1]"
                      />
                    }
                    aria-label={backLabel}
                    onClick={onBack}
                  />
                </div>
              )}
              <span className={mergeClasses(styles.title, titleClassName)}>
                {title}
              </span>
              <div className="absolute end-4 m-2">
                <CloseButton
                  ariaLabel={closeLabel}
                  onClose={onClose}
                  size={ElementSize.Standard}
                />
              </div>
            </div>
            <div
              className={mergeClasses(styles.divider, 'h-px flex-shrink-0')}
            />
          </>
        )}
        <div className="overflow-y-auto">{children}</div>
      </div>
    </>,
    document.body,
  );
}

export interface BottomSheetShellProps {
  /** Controls sheet visibility. */
  isOpen: boolean;
  /** Heading text for the sheet header and dialog accessible name; header hidden when omitted. */
  title?: string;
  /** Accessible label for the close (×) button. Required when `title` is provided. */
  closeLabel?: string;
  /** Called when the sheet should close (backdrop tap, close button, or Escape). */
  onClose: () => void;
  /** When provided, a back-arrow button is shown at the start of the header. */
  onBack?: () => void;
  /** Accessible label for the back button. Required when `onBack` is provided. */
  backLabel?: string;
  /** Dialog accessible name used when `title` is omitted. */
  'aria-label'?: string;
  /** Inline CSS custom properties forwarded to the sheet root for theming. */
  style?: CSSProperties;
  /** CSS class applied to the sheet title. Defaults to `'dial-body-semi-text'`. */
  titleClassName?: string;
  /** Extra classes appended to the sheet container (e.g. a max-height constraint). */
  className?: string;
  /** Color overrides applied as CSS custom properties. */
  colors?: BottomSheetShellColors;
  /** Sheet body rendered below the header divider. */
  children: ReactNode;
}

ConversationInput: FC<ConversationInputProps> = ({
  isStreaming = false,
  placeholder = 'Type a prompt or use "/" to select one',
  welcomeText,
  descriptionText,
  styles: stylesProp,
  className,
  inputClassName,
  isInputDisabled = false,
  ...inputProps
}) => {
  const { colors, typography } = stylesProp ?? {};

  const cssVars = buildCssVars({
    '--ci-welcome-color': colors?.welcomeText,
    '--ci-description-color': colors?.descriptionText,
  });

  return (
    <div
      style={cssVars}
      className={mergeClasses(
        'relative flex w-full flex-col items-center gap-9 px-4 py-5 desktop:p-5',
        className,
      )}
    >
      {welcomeText && (
        <div className="flex flex-col items-center gap-4 text-center">
          <h1
            className={mergeClasses(
              styles.welcome,
              'm-0',
              typography?.welcomeClassName || 'dial-display2-text',
            )}
          >
            {welcomeText}
          </h1>
          {descriptionText && (
            <p
              className={mergeClasses(
                styles.description,
                'm-0 max-w-[540px]',
                typography?.descriptionClassName || 'dial-body-paragraph-text',
              )}
            >
              {descriptionText}
            </p>
          )}
        </div>
      )}
      <div
        className={mergeClasses(
          'relative w-full',
          /* Narrower composer on the welcome screen only; the active-chat
           * input keeps the 748px width shared with `Input`/`VoiceBar`. */
          welcomeText ? 'max-w-[700px]' : 'max-w-[748px]',
        )}
      >
        <Input
          placeholder={placeholder}
          isStreaming={isStreaming}
          isInputDisabled={isInputDisabled}
          {...inputProps}
          className={inputClassName}
          colors={colors?.input}
          typography={typography?.input}
        />
      </div>
    </div>
  );
}

EditMessageInput: FC<EditMessageInputProps> = ({
  message,
  inlineStartSlot,
  onInlineStartRemove,
  initialAttachments = [],
  onCancel,
  onSave,
  onUploadAttachment,
  cancelLabel = 'Cancel',
  saveLabel = 'Save & Submit',
  ariaLabel,
  removeLabel,
  retryLabel,
  uploadingLabel,
  addMenuTitle = 'Add',
  attachLabel = 'Attach file',
  menuTitle = 'Menu',
  menuCloseLabel = 'Close',
  className,
  pendingDropFiles: externalPendingFiles,
  onDropFilesConsumed,
  validateAttachment,
  isAttachmentsEnabled,
  isTextAttachmentsAllowed,
  hideAttachFile = false,
  fileAccept,
  maximumAttachmentsAmount,
  onAttachmentsLimitExceeded,
  onDialFileSystemClick,
  dialFileSystemLabel,
  pendingAttachments,
  onPendingAttachmentsConsumed,
  onAttachmentClick,
  pasteTextThreshold,
  maxMessageLength = 50000,
  onMessageTooLong,
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [pendingDropFiles, setPendingDropFiles] = useState<File[]>([]);

  useEffect(() => {
    if (!externalPendingFiles?.length) return;
    setPendingDropFiles(externalPendingFiles);
    onDropFilesConsumed?.();
  }, [externalPendingFiles, onDropFilesConsumed]);
  const [currentText, setCurrentText] = useState(message ?? '');
  const [currentNewAttachments, setCurrentNewAttachments] = useState<
    Attachment[]
  >([]);
  const [keptAttachments, setKeptAttachments] =
    useState<DisplayAttachment[]>(initialAttachments);

  const hasBlockedNewAttachments = currentNewAttachments.some(
    (attachment) =>
      attachment.status === RequestStatus.Loading ||
      attachment.status === RequestStatus.Error,
  );
  const canSend =
    (currentText.trim().length > 0 ||
      currentNewAttachments.length > 0 ||
      keptAttachments.length > 0) &&
    !hasBlockedNewAttachments;

  const handleRemovePreExisting = (id: string) => {
    setKeptAttachments((prev) => prev.filter((a) => a.id !== id));
  };

  // Called by Input's Enter-key path and by the external Save button.
  const handleSend = useCallback(
    (text: string, newAttachments: Attachment[]) => {
      onSave(text, keptAttachments, newAttachments);
    },
    [keptAttachments, onSave],
  );

  const handleSaveClick = () => {
    if (!canSend) return;
    if (currentText.length >= maxMessageLength) {
      onMessageTooLong?.(currentText.length, maxMessageLength);
      return;
    }
    handleSend(currentText, currentNewAttachments);
  };

  const handleDropFilesConsumed = useCallback(
    () => setPendingDropFiles([]),
    [],
  );

  const handleFileChange = useCallback((e: ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files ?? []);
    if (files.length === 0) return;
    e.target.value = '';
    setPendingDropFiles(files);
  }, []);

  const dialFileSystemMenuItem = useMemo(
    () =>
      onDialFileSystemClick
        ? [
            {
              key: 'dial-fs',
              label: dialFileSystemLabel ?? 'DIAL file system',
              icon: (
                <IconFile
                  size={BASE_ICON_SIZE}
                  aria-hidden
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              ),
              onClick: onDialFileSystemClick,
            },
          ]
        : [],
    [onDialFileSystemClick, dialFileSystemLabel],
  );

  return (
    <div className={mergeClasses('flex w-full flex-col gap-2', className)}>
      {/* Bordered box — contains kept attachments, new attachments, and the textarea */}
      <Input
        message={message}
        inlineStartSlot={inlineStartSlot}
        onInlineStartRemove={onInlineStartRemove}
        ariaLabel={ariaLabel}
        hideActionBar
        pendingDropFiles={pendingDropFiles}
        onDropFilesConsumed={handleDropFilesConsumed}
        onSend={handleSend}
        onUploadAttachment={onUploadAttachment}
        onChange={setCurrentText}
        onAttachmentsChange={setCurrentNewAttachments}
        removeLabel={removeLabel}
        retryLabel={retryLabel}
        uploadingLabel={uploadingLabel}
        className="max-w-full"
        prefixAttachments={keptAttachments}
        onRemovePrefixAttachment={handleRemovePreExisting}
        validateAttachment={validateAttachment}
        isAttachmentsEnabled={isAttachmentsEnabled}
        isTextAttachmentsAllowed={isTextAttachmentsAllowed}
        maximumAttachmentsAmount={maximumAttachmentsAmount}
        onAttachmentsLimitExceeded={onAttachmentsLimitExceeded}
        pendingAttachments={pendingAttachments}
        onPendingAttachmentsConsumed={onPendingAttachmentsConsumed}
        onAttachmentClick={onAttachmentClick}
        pasteTextThreshold={pasteTextThreshold}
        maxMessageLength={maxMessageLength}
        onMessageTooLong={onMessageTooLong}
      />

      {/* Action row — outside the bordered box */}
      <div className="flex items-center justify-between">
        <div className="flex">
          {!hideAttachFile && (
            <>
              <input
                ref={fileInputRef}
                type="file"
                multiple
                accept={fileAccept}
                className="sr-only"
                aria-hidden
                tabIndex={-1}
                onChange={handleFileChange}
              />
              <AddAttachmentButton
                onAttachClick={() => fileInputRef.current?.click()}
                attachLabel={attachLabel}
                addMenuTitle={addMenuTitle}
                menuTitle={menuTitle}
                menuCloseLabel={menuCloseLabel}
                extraMenuItems={dialFileSystemMenuItem}
              />
            </>
          )}
        </div>

        <div className="flex gap-2">
          <NeutralButton label={cancelLabel} onClick={onCancel} />
          <PrimaryButton
            label={saveLabel}
            onClick={handleSaveClick}
            disabled={!canSend}
          />
        </div>
      </div>
    </div>
  );
}

Input: FC<InputProps> = ({
  message: messageProp = '',
  messageRevision,
  textInsertion,
  onSend,
  onUploadAttachment,
  onStop,
  isStreaming = false,
  onChange,
  onAttachmentsChange,
  placeholder = 'Type a message...',
  ariaLabel,
  attachLabel = 'Attach file',
  fileAccept,
  addMenuTitle = 'Add',
  menuTitle = 'Menu',
  menuCloseLabel = 'Close',
  removeLabel,
  retryLabel,
  uploadingLabel,
  sendLabel,
  sendTooltip,
  emptyMessageTooltip,
  stopLabel,
  micLabel = 'Dictate',
  recordVoiceLabel = 'Record voice',
  stopRecordingLabel,
  discardRecordingLabel,
  colors,
  typography,
  className,
  pendingDropFiles = [],
  onDropFilesConsumed,
  pendingAttachments = [],
  onPendingAttachmentsConsumed,
  pasteTextThreshold = 4000,
  maxMessageLength = 50000,
  deployments,
  selectedDeploymentId,
  onDeploymentChange,
  modelSelectorLabels,
  initialAttachments = [],
  hideAddButton = false,
  hideAttachFile = false,
  hideActionBar = false,
  actionRowLayout = ActionRowLayout.Stacked,
  renderFooterActions,
  isInputDisabled = false,
  isModelSelectorDisabled = false,
  isSendDisabled = false,
  isAudioMessageSupported = false,
  isVoiceRecordingSupported = isAudioMessageSupported,
  onTranscribeAudio,
  transcribingLabel,
  voiceErrorLabel,
  sendOnEnter = SendOnEnter.Enter,
  prefixAttachments = [],
  onRemovePrefixAttachment,
  chatSettings,
  toolsMenuItems,
  onToolToggle,
  canRemoveTools = true,
  toolsMenuTitle,
  toolsBackLabel,
  toolsChipLabels,
  menuOverlays,
  inlineStartSlot,
  onInlineStartRemove,
  commandMenu,
  autoFocus = false,
  messageHistory,
  onDialFileSystemClick,
  dialFileSystemLabel,
  validateAttachment,
  onAttachmentClick,
  modelPickerOverlay,
  maximumAttachmentsAmount,
  onAttachmentsLimitExceeded,
  isAttachmentsEnabled = true,
  isTextAttachmentsAllowed = true,
  usageLimitsSlot,
  onMessageTooLong,
}) => {
  const isMobile = useIsMobile();
  const [isPickerOpen, setIsPickerOpen] = useState(false);
  const historyNav = useInputHistoryNavigation(messageHistory);
  const hasInlineStartSlot = inlineStartSlot != null;
  const [inlineStartSlotNode, setInlineStartSlotNode] =
    useState<HTMLDivElement | null>(null);
  const [inlineStartIndent, setInlineStartIndent] = useState(0);

  const cssVars = useMemo(
    () =>
      buildCssVars({
        '--ci-bg': colors?.background,
        '--ci-text': colors?.text,
        '--ci-border': colors?.border,
        '--ci-border-focus': colors?.borderFocus,
        '--ci-placeholder': colors?.placeholder,
        '--ci-text-disabled': colors?.textDisabled,
        '--ci-model-selector-caret-color': colors?.modelSelectorCaret,
        '--ci-model-selector-hover-bg': colors?.modelSelectorHoverBg,
        '--ci-model-selector-disabled-color': colors?.modelSelectorDisabled,
        '--ci-model-selector-name-color': colors?.modelSelectorName,
        '--ci-model-selector-version-color': colors?.modelSelectorVersion,
        '--ci-voice-error': colors?.voiceError,
        '--ci-voice-waveform': colors?.voiceWaveform,
        '--ci-voice-accent': colors?.voiceAccent,
        /*
         * Where the textarea's first text line starts (the inline-start
         * slot's width plus a caret gap while a slot is present, unset
         * otherwise) — shared by the first-line `text-indent` and the
         * command-menu hint overlay so both start at the same offset.
         */
        '--ci-first-line-indent': hasInlineStartSlot
          ? `calc(${inlineStartIndent}px + 4px)`
          : undefined,
      }),
    [colors, hasInlineStartSlot, inlineStartIndent],
  );

  const dialFileSystemMenuItem = useMemo(
    () =>
      onDialFileSystemClick
        ? [
            {
              key: 'dial-fs',
              label: dialFileSystemLabel ?? 'DIAL file system',
              icon: (
                <IconFile
                  size={BASE_ICON_SIZE}
                  aria-hidden
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              ),
              onClick: onDialFileSystemClick,
            },
          ]
        : [],
    [onDialFileSystemClick, dialFileSystemLabel],
  );

  const { message, setMessage, textareaRef } = useMessageState({
    messageProp,
    messageRevision,
  });

  const { handleUndoKeyDown } = useTextInsertion({
    insertion: textInsertion,
    textareaRef,
  });

  const { isMenuOpen, query, dismiss, handleValueChange } = useCommandMenu({
    config: commandMenu,
    message,
  });

  /*
   * The command menu's empty-query hint: while the menu is open the value is
   * the trigger prefix plus the query, so an empty query means the textarea
   * holds exactly the prefix — the hint renders right after it and disappears
   * with the first query keystroke. This gates only the hint overlay itself:
   * the textarea's wrapper below is driven by the hint's *configuration*, not
   * the live menu state, so the hint appearing and disappearing never
   * remounts the textarea mid-typing.
   */
  const hasCommandHintConfigured = commandMenu?.emptyQueryHint != null;
  const hasCommandEmptyQueryHint =
    hasCommandHintConfigured && isMenuOpen && query === '';

  /*
   * Selection path of the command menu: removes the `/query` text from the
   * textarea so it is never sent, resets the draft-history state to match,
   * and notifies the host. The consume lives here because the textarea value
   * is owned by this component — a host-side removal would race the lib.
   */
  const handleCloseCommandMenu = useCallback(
    (options?: { consumeQuery?: boolean }) => {
      if (commandMenu == null) return;

      dismiss();
      if (!options?.consumeQuery) return;

      /*
       * A selection made by mouse moved focus to the menu row, and that row
       * unmounts with the menu — return focus to the textarea so typing
       * continues where the consumed `/query` left off.
       */
      textareaRef.current?.focus();

      const consumed = `${commandMenu.triggerPrefix}${query}`;
      if (!message.startsWith(consumed)) return;

      const nextMessage = message.slice(consumed.length);
      setMessage(nextMessage);
      historyNav.notifyChange();
      onChange?.(nextMessage);
    },
    [
      commandMenu,
      dismiss,
      query,
      message,
      setMessage,
      historyNav,
      onChange,
      textareaRef,
    ],
  );

  useEffect(() => {
    if (inlineStartSlotNode == null) return;
    /*
     * The slot's width drives the textarea's first-line `text-indent`, so it
     * is re-measured whenever the slot's content resizes (e.g. a different
     * element of a different width) and whenever the slot node itself
     * (re)mounts — e.g. the slot is hidden behind `VoiceBar` while recording
     * and reappears once recording stops, which does not change
     * `hasInlineStartSlot` and so would never re-trigger a `useEffect` keyed
     * on that flag alone.
     */
    const observer = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (entry != null) setInlineStartIndent(entry.contentRect.width);
    });
    observer.observe(inlineStartSlotNode);
    return () => observer.disconnect();
  }, [inlineStartSlotNode]);

  const handleExpandPastedText = useCallback(
    (text: string) => {
      setMessage((prev) => (prev ? `${prev}\n${text}` : text));
    },
    [setMessage],
  );

  const {
    attachments,
    buildAttachments,
    addAttachments,
    resetAttachments,
    handleRemove,
    handleRetry,
    handleExpand,
    hasBlockedAttachments,
  } = useAttachments({
    initialAttachments,
    onUploadAttachment,
    onAttachmentsChange,
    validateAttachment,
    pendingDropFiles,
    onDropFilesConsumed,
    pendingAttachments,
    onPendingAttachmentsConsumed,
    onExpandPastedText: handleExpandPastedText,
    maximumAttachmentsAmount,
    baseAttachmentsAmount: prefixAttachments.length,
    onAttachmentsLimitExceeded,
  });

  const handleAttachAudio = useCallback(
    (file: File) => {
      addAttachments(buildAttachments([file]));
    },
    [addAttachments, buildAttachments],
  );

  const focusAfterTranscriptRef = useRef(false);
  const draftRef = useRef(message);
  draftRef.current = message;
  const [latestTranscript, setLatestTranscript] = useState({
    text: '',
    revision: 0,
  });
  const handleTranscript = useCallback(
    (text: string) => {
      const transcript = text.trim();
      if (transcript) {
        const draft = draftRef.current;
        const nextMessage = `${draft}${draft && !/\s$/.test(draft) ? ' ' : ''}${transcript}`;
        draftRef.current = nextMessage;
        setMessage(nextMessage);
        setLatestTranscript((previous) => ({
          text: transcript,
          revision: previous.revision + 1,
        }));
        historyNav.notifyChange();
        onChange?.(nextMessage);
      }
      focusAfterTranscriptRef.current = true;
    },
    [setMessage, historyNav, onChange],
  );

  const {
    state: voiceState,
    analyserNodeRef,
    errorMessage: voiceError,
    startRecording,
    stopRecording,
    discardRecording,
  } = useVoiceRecorder({
    onAttachAudio: handleAttachAudio,
    onTranscribeAudio,
    onTranscript: handleTranscript,
    errorLabel: voiceErrorLabel,
  });
  const isVoiceActive =
    voiceState === VoiceRecorderState.Recording ||
    voiceState === VoiceRecorderState.Processing;

  useEffect(() => {
    if (
      voiceState === VoiceRecorderState.Error ||
      (voiceState === VoiceRecorderState.Idle &&
        focusAfterTranscriptRef.current)
    ) {
      focusAfterTranscriptRef.current = false;
      textareaRef.current?.focus();
    }
  }, [voiceState, textareaRef]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  /*
   * A long plain-text paste becomes a `text/plain` attachment only when the
   * selected model would accept one: `isAttachmentsEnabled` says attachments
   * are supported at all, `isTextAttachmentsAllowed` says a `text/plain`
   * attachment would pass the host's validation. On a model that accepts
   * only other kinds of attachments (e.g. images only), converting the paste
   * would produce an attachment the model rejects.
   */
  const isPasteAsAttachmentEnabled =
    isAttachmentsEnabled && isTextAttachmentsAllowed;
  const { handlePaste: handleClipboardPaste } = useClipboardPaste(
    addAttachments,
    isPasteAsAttachmentEnabled ? pasteTextThreshold : Infinity,
  );

  const handlePaste = useCallback(
    (e: ClipboardEvent<HTMLTextAreaElement>) => {
      /*
       * Deliberately narrower than the send gate above. When a paste becomes
       * an attachment it never reaches the textarea, so warning here would be
       * about text the user did not paste inline; an under-threshold paste is
       * at most pasteTextThreshold characters and cannot reach the cap on its
       * own. Existing text plus a small paste crossing the cap is not visible
       * from the pasted string's length at all — the send gate catches that.
       */
      if (!isPasteAsAttachmentEnabled) {
        const text = e.clipboardData.getData('text/plain');
        if (text.length >= maxMessageLength) {
          onMessageTooLong?.(text.length, maxMessageLength);
        }
      }
      handleClipboardPaste(e);
    },
    [
      isPasteAsAttachmentEnabled,
      maxMessageLength,
      onMessageTooLong,
      handleClipboardPaste,
    ],
  );

  /*
   * The inline-start slot (a selected skill) counts as sendable content on
   * its own: the host's send-time payload includes it, so a skill with an
   * empty draft is a valid message and the send button mounts and enables.
   */
  const hasSendableContent =
    message.trim().length > 0 || attachments.length > 0 || hasInlineStartSlot;
  const canSend =
    hasSendableContent &&
    !hasBlockedAttachments &&
    !isSendDisabled &&
    !isVoiceActive;
  /*
   * Chips the user dismissed with the chip's ×. Dismissal is view state of this
   * input only: a dismissed tool comes back the moment it is switched on again
   * from the `+` menu, and the whole set is forgotten when the deployment
   * offers a different list of tools.
   */
  const [dismissedToolIds, setDismissedToolIds] = useState<string[]>([]);
  const toolIdsSignature = (toolsMenuItems ?? [])
    .map((tool) => tool.id)
    .join('|');

  useEffect(() => {
    setDismissedToolIds([]);
  }, [toolIdsSignature]);

  const visibleTools = useMemo(() => {
    const tools = toolsMenuItems ?? [];
    if (!canRemoveTools) return tools;
    return tools.filter(
      (tool) => tool.isSelected || !dismissedToolIds.includes(tool.id),
    );
  }, [toolsMenuItems, dismissedToolIds, canRemoveTools]);

  const handleToolDismiss = useCallback(
    (toolId: string) => {
      setDismissedToolIds((prev) =>
        prev.includes(toolId) ? prev : [...prev, toolId],
      );
      const tool = toolsMenuItems?.find((item) => item.id === toolId);
      if (tool?.isSelected) onToolToggle?.(toolId);
    },
    [toolsMenuItems, onToolToggle],
  );

  const hasModelSelected =
    deployments === undefined || selectedDeploymentId != null;
  const shouldShowMicButton = isAudioMessageSupported && !isStreaming;

  const handleSend = async () => {
    if (isSendDisabled || isVoiceActive) return;
    if (message.length >= maxMessageLength) {
      onMessageTooLong?.(message.length, maxMessageLength);
      return;
    }

    const currentMessage = message;
    const currentAttachments = attachments;
    setMessage('');
    historyNav.reset();
    try {
      await onSend?.(currentMessage, currentAttachments);
      currentAttachments.forEach((a) => {
        if (a.previewUrl) URL.revokeObjectURL(a.previewUrl);
        if (a.playUrl) URL.revokeObjectURL(a.playUrl);
      });
      resetAttachments([]);
    } catch {
      setMessage(currentMessage);
      resetAttachments(currentAttachments);
    }
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (isVoiceActive) return;
    /* Serves the undo owed by an insertion the browser could not put on its own
       undo stack; a no-op whenever the browser can undo the edit itself. */
    if (handleUndoKeyDown(e)) return;
    if (!e.nativeEvent.isComposing && !isInputDisabled && !isStreaming) {
      if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
        const cursorPos = e.currentTarget.selectionStart ?? 0;
        const newValue = historyNav.navigate(
          e.key === 'ArrowUp' ? 'up' : 'down',
          message,
          cursorPos,
        );
        if (newValue !== null) {
          e.preventDefault();
          setMessage(newValue);
          return;
        }
      }

      /*
       * The slot's remove gesture: a Backspace with the caret collapsed at
       * position 0 has nothing to delete backwards, so it is redirected to
       * the inline-start slot instead — the standard chip-removal gesture of
       * chat composers.
       */
      if (
        e.key === 'Backspace' &&
        hasInlineStartSlot &&
        onInlineStartRemove != null &&
        e.currentTarget.selectionStart === 0 &&
        e.currentTarget.selectionEnd === 0
      ) {
        e.preventDefault();
        onInlineStartRemove();
        return;
      }
    }

    const isEnterKey = e.key === 'Enter';
    if (!isEnterKey) return;

    const shouldSend =
      sendOnEnter === SendOnEnter.MetaEnter
        ? (e.metaKey || e.ctrlKey) && !e.shiftKey
        : !e.shiftKey && !e.metaKey && !e.ctrlKey;

    if (shouldSend) {
      e.preventDefault();
      if (!isStreaming && canSend && hasModelSelected && !isInputDisabled) {
        handleSend();
      }
    }
  };

  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files ?? []);
    if (files.length === 0) return;
    const newAttachments = buildAttachments(files);
    // Reset so the same file can be picked again
    e.target.value = '';
    addAttachments(newAttachments);
  };

  const textarea = (
    <textarea
      className={mergeClasses(
        styles.textarea,
        hasInlineStartSlot && styles.textareaIndented,
        typography?.fontClassName || 'dial-body-paragraph-text',
        'max-h-[272px] w-full resize-none overflow-y-auto border-0 bg-transparent outline-none [field-sizing:content]',
        'disabled:cursor-not-allowed',
      )}
      ref={textareaRef}
      autoFocus={autoFocus}
      value={message}
      onChange={(e) => {
        setMessage(e.target.value);
        historyNav.notifyChange();
        /*
         * React types `ChangeEvent`'s `nativeEvent` as bare `Event`; the
         * runtime event behind a textarea's change is an `InputEvent`, so
         * narrow with `instanceof` to read `isComposing` and `inputType` — a
         * non-InputEvent can't be mid-composition or a paste, hence the
         * defaults.
         */
        const inputEvent =
          e.nativeEvent instanceof InputEvent ? e.nativeEvent : undefined;
        handleValueChange(
          e.target.value,
          inputEvent?.isComposing ?? false,
          inputEvent?.inputType,
        );
        onChange?.(e.target.value);
      }}
      onKeyDown={handleKeyDown}
      onPaste={handlePaste}
      /* The placeholder is suppressed while a slot occupies the first line: the slot itself says what the input holds. */
      placeholder={hasInlineStartSlot ? undefined : placeholder}
      aria-label={ariaLabel}
      disabled={isInputDisabled}
      readOnly={isVoiceActive}
      rows={1}
    />
  );

  /*
   * The command menu anchors to the textarea itself: the kit `Dropdown` runs
   * with interactions off (`trigger={[]}`) so the controlled `open` is the
   * only opener, keeps focus in the textarea on open (`initialFocus={-1}`)
   * so typing continues to filter, and treats clicks inside the textarea as
   * inside the menu (`outsidePressIgnoreRef`). `className="w-full"` offsets
   * the kit trigger wrapper's flex display so the textarea keeps full width.
   * `matchReferenceWidth={false}` drops the kit's default min-width equal to
   * the textarea's width, so the overlay sizes to its rendered content
   * instead of stretching across the whole input.
   */
  const commandMenuArea =
    commandMenu == null ? (
      textarea
    ) : (
      <Dropdown
        className="w-full"
        open={isMenuOpen}
        onOpenChange={(isOpen) => {
          if (!isOpen) dismiss();
        }}
        placement="top-start"
        trigger={[]}
        initialFocus={-1}
        matchReferenceWidth={false}
        outsidePressIgnoreRef={textareaRef}
        renderOverlay={() => {
          const menu = commandMenu.renderMenu({
            query,
            close: handleCloseCommandMenu,
          });
          if (commandMenu.menuLabel == null) {
            return menu;
          }
          return (
            <div role="group" aria-label={commandMenu.menuLabel}>
              {menu}
            </div>
          );
        }}
      >
        {textarea}
      </Dropdown>
    );

  /*
   * The inline-start slot overlays the textarea's first line from inside its
   * container: the slot is absolutely positioned at the inline-start edge of
   * the first line, the first text line indents past it via
   * `--ci-first-line-indent`, and slot content whose height is one label
   * line (the ChatSkill chip) aligns with the first text line exactly. Every
   * following line keeps the full width (a textarea is one paragraph block,
   * so `text-indent` applies to its first line only). The same wrapper hosts
   * the command menu's empty-query hint overlay. The wrapper's presence is
   * decided by configuration only — a slot is present, a hint is configured —
   * never by live menu state: toggling an ancestor of the textarea when the
   * menu opens or when the hint appears/disappears would remount it and throw
   * away focus and the caret mid-typing. Without either configured the
   * wrapper collapses to the bare textarea, byte-identical to the slot-less
   * rendering.
   */
  const textareaArea =
    hasInlineStartSlot || hasCommandHintConfigured ? (
      <div className="relative w-full">
        {hasInlineStartSlot && (
          <div ref={setInlineStartSlotNode} className="absolute start-0 top-0">
            {inlineStartSlot}
          </div>
        )}
        {hasCommandEmptyQueryHint && commandMenu != null && (
          <span
            className={mergeClasses(
              styles.commandHint,
              'pointer-events-none absolute start-[var(--ci-first-line-indent,0px)] top-0',
              typography?.fontClassName || 'dial-body-paragraph-text',
            )}
            aria-hidden
          >
            {/*
             * The invisible mirror of the trigger prefix occupies exactly the
             * prefix's rendered width in the textarea's own typography, so
             * the hint lands immediately after the real prefix without
             * measuring anything. `aria-hidden`: the hint restates the open
             * menu, which announces itself.
             */}
            <span className="invisible">{commandMenu.triggerPrefix}</span>
            {commandMenu.emptyQueryHint}
          </span>
        )}
        {commandMenuArea}
      </div>
    ) : (
      commandMenuArea
    );

  /*
   * Shared between the normal footer and the voice bar's second row: same
   * menu, same file input, only its disabled state differs. Disabled while
   * a dictation/attachment recording is anything but actively Recording, so
   * it cannot be used to interrupt a pending transcription.
   */
  const attachButtonNode = hideAddButton ? undefined : (
    <AddAttachmentButton
      onAttachClick={
        hideAttachFile ? undefined : () => fileInputRef.current?.click()
      }
      attachLabel={attachLabel}
      addMenuTitle={addMenuTitle}
      menuTitle={menuTitle}
      menuCloseLabel={menuCloseLabel}
      style={cssVars}
      isDisabled={isInputDisabled || isVoiceActive}
      chatSettings={chatSettings}
      extraMenuItems={dialFileSystemMenuItem}
      onRecordVoice={
        isVoiceRecordingSupported &&
        isAttachmentsEnabled &&
        !isStreaming &&
        !isVoiceActive
          ? () => startRecording(VoiceRecordingMode.Attachment)
          : undefined
      }
      recordVoiceLabel={recordVoiceLabel}
      /*
       * The "Tools" submenu exists only to bring a dismissed chip
       * back. With removal off every chip is always on screen, so the
       * entry would be dead weight — and where tools are the menu's
       * only content, withholding them drops the `+` button entirely.
       */
      toolsMenuItems={canRemoveTools ? toolsMenuItems : undefined}
      onToolToggle={onToolToggle}
      toolsMenuTitle={toolsMenuTitle}
      toolsBackLabel={toolsBackLabel}
      menuOverlays={menuOverlays}
    />
  );

  /*
   * One line does not fit a phone, so the inline layout is desktop-only and a
   * host does not have to branch on viewport itself.
   */
  const isInlineActionRow =
    actionRowLayout === ActionRowLayout.Inline && !isMobile;

  const addClusterNode = attachButtonNode && (
    <div className={mergeClasses('flex', CONVERSATION_INPUT_CLASS.addCluster)}>
      {attachButtonNode}
    </div>
  );

  const chipsNode = visibleTools.length > 0 && onToolToggle != null && (
    <div
      className={mergeClasses(
        'min-w-0 flex-1',
        CONVERSATION_INPUT_CLASS.toolsChips,
      )}
    >
      <ToolsChips
        items={visibleTools}
        onToolToggle={onToolToggle}
        onToolDismiss={handleToolDismiss}
        canRemove={canRemoveTools}
        removeLabel={toolsChipLabels?.removeLabel}
      />
    </div>
  );

  return (
    <div
      ref={containerRef}
      style={cssVars}
      className={mergeClasses(
        styles.wrapper,
        isInputDisabled && styles.wrapperDisabled,
        isInputDisabled && 'cursor-not-allowed',
        'flex w-full max-w-[748px] flex-col justify-center gap-3 rounded-xl border',
        'focus-within:outline focus-within:-outline-offset-1 active:outline active:-outline-offset-1',
        attachments.length > 6 ? 'py-4 ps-4' : 'p-4',
        className,
        CONVERSATION_INPUT_CLASS.wrapper,
      )}
    >
      {(prefixAttachments.length > 0 || attachments.length > 0) && (
        <AttachmentTray
          attachments={[...prefixAttachments, ...attachments]}
          onRemove={(id) => {
            if (prefixAttachments.some((a) => a.id === id)) {
              onRemovePrefixAttachment?.(id);
            } else {
              handleRemove(id);
            }
          }}
          onRetry={handleRetry}
          onExpand={handleExpand}
          labels={{ removeLabel, retryLabel, uploadingLabel }}
          onAttachmentClick={
            onAttachmentClick != null
              ? (id) => {
                  const found = [...prefixAttachments, ...attachments].find(
                    (a) => a.id === id,
                  );
                  if (found != null) onAttachmentClick(found);
                }
              : undefined
          }
        />
      )}
      {!hideAddButton && (
        <input
          ref={fileInputRef}
          type="file"
          multiple
          accept={fileAccept}
          className="sr-only"
          aria-hidden
          tabIndex={-1}
          onChange={handleFileChange}
        />
      )}
      {voiceError && (
        <ErrorText text={voiceError} className="min-w-0 break-words px-1" />
      )}
      {isVoiceActive && (
        <VoiceBar
          embedded
          state={voiceState}
          analyserNodeRef={analyserNodeRef}
          errorMessage={voiceError}
          onStop={stopRecording}
          onDiscard={discardRecording}
          attachButton={attachButtonNode}
          stopLabel={stopRecordingLabel}
          discardLabel={discardRecordingLabel}
          processingLabel={transcribingLabel}
        />
      )}
      {!isVoiceActive && hideActionBar && textareaArea}
      {/*
       * Tool chips are variable-width, so in the inline layout they get their
       * own row above rather than competing with the textarea for the line.
       */}
      {!isVoiceActive && !hideActionBar && isInlineActionRow && chipsNode && (
        <div className="flex">{chipsNode}</div>
      )}
      {!isVoiceActive && !hideActionBar && (
        <div
          className={mergeClasses(
            'flex items-center gap-2',
            isInlineActionRow ? 'flex-nowrap' : 'flex-wrap',
            CONVERSATION_INPUT_CLASS.actionRow,
          )}
        >
          {/*
           * Both layouts render in visual order rather than reordering with
           * `order-*`, so the tab order always matches what is on screen.
           */}
          {isInlineActionRow && addClusterNode}
          <div
            className={mergeClasses(
              'flex min-w-0 items-center self-stretch',
              isInlineActionRow ? 'flex-1' : 'w-full',
              CONVERSATION_INPUT_CLASS.textareaWrap,
            )}
          >
            {textareaArea}
          </div>
          {!isInlineActionRow && addClusterNode}
          {!isInlineActionRow && chipsNode}
          <div
            className={mergeClasses(
              'ms-auto flex flex-shrink-0 items-center gap-2',
              CONVERSATION_INPUT_CLASS.footerActions,
            )}
          >
            {renderFooterActions ? (
              renderFooterActions({ canSend, onSend: handleSend })
            ) : (
              <>
                {usageLimitsSlot}
                <ModelSelectorControl
                  deployments={deployments}
                  selectedDeploymentId={selectedDeploymentId}
                  onDeploymentChange={onDeploymentChange}
                  modelSelectorLabels={modelSelectorLabels}
                  isStreaming={isStreaming}
                  isMobile={isMobile}
                  isDisabled={isModelSelectorDisabled}
                  style={cssVars}
                  modelPickerOverlay={modelPickerOverlay}
                  isPickerOpen={isPickerOpen}
                  onPickerToggle={() => setIsPickerOpen((prev) => !prev)}
                  onPickerOpenChange={setIsPickerOpen}
                />
                {shouldShowMicButton && (
                  <GhostIconButton
                    icon={
                      <IconMicrophone
                        size={DIAL_ICON_SIZE.LG}
                        stroke={DIAL_KIT_ICON_STROKE}
                        aria-hidden
                      />
                    }
                    aria-label={micLabel}
                    tooltipProps={{ tooltip: micLabel }}
                    className="size-[40px] flex-shrink-0 mobile:min-h-11 mobile:min-w-11"
                    onClick={() => startRecording(VoiceRecordingMode.Dictation)}
                    disabled={isInputDisabled || isStreaming}
                  />
                )}
                {isStreaming && onStop ? (
                  <StopButton onStop={onStop} ariaLabel={stopLabel} />
                ) : (
                  !isStreaming && (
                    <SendButton
                      onSend={handleSend}
                      isDisabled={!hasModelSelected || !canSend}
                      ariaLabel={sendLabel}
                      sendTooltip={
                        hasSendableContent
                          ? sendTooltip
                          : (emptyMessageTooltip ?? sendTooltip)
                      }
                    />
                  )
                )}
              </>
            )}
          </div>
        </div>
      )}
      <span
        className="sr-only"
        role="status"
        aria-live="polite"
        aria-atomic="true"
      >
        <span key={latestTranscript.revision}>{latestTranscript.text}</span>
      </span>
    </div>
  );
}

export interface ConversationInputColors {
  /** Welcome heading text color. */
  welcomeText?: string;
  /** Description text color, shown below the welcome heading. */
  descriptionText?: string;
  /** Color overrides forwarded to the inner `Input` component. */
  input?: InputColors;
}

export interface ConversationInputProps {
  /** Placeholder text shown inside the textarea when empty. */
  placeholder?: string;
  /**
   * How the action row arranges the textarea and the controls around it.
   * Defaults to `ActionRowLayout.Stacked`. `ActionRowLayout.Inline` is ignored
   * on mobile, where one line does not fit.
   */
  actionRowLayout?: ActionRowLayout;
  /**
   * Message value. Sets the initial textarea content on mount and syncs the
   * textarea whenever the value changes.
   */
  message?: string;
  /**
   * Optional token that forces the textarea to resync from `message`, even
   * when `message` itself is the same string as before.
   */
  messageRevision?: number;
  /**
   * Text inserted at the caret each time its `revision` changes, leaving the
   * surrounding draft intact. Unlike `message`, this never replaces what the
   * user has written, and it is made through the browser's editing pipeline so
   * the native undo shortcut reverts it.
   */
  textInsertion?: TextInsertion;
  /** Optional welcome heading rendered above the input. */
  welcomeText?: string;
  /** Optional description text rendered below the welcome heading. Ignored when `welcomeText` is absent. */
  descriptionText?: string;
  /** Called when the user submits a message (Enter or send button). Receives the current local attachments as the second argument. */
  onSend?: (message: string, attachments: Attachment[]) => void;
  /** Called immediately after an attachment is added. Returns the uploaded attachment URL and stored name. */
  onUploadAttachment?: (
    attachment: Attachment,
  ) => Promise<UploadedAttachmentResult>;
  /** Called when the user clicks the stop button during streaming. */
  onStop?: () => void;
  /** When `true`, shows a stop button instead of the send button and blocks Enter. */
  isStreaming?: boolean;
  /** Called whenever the attachment list changes. */
  onAttachmentsChange?: (attachments: Attachment[]) => void;
  /** Color and typography overrides applied as CSS custom properties. */
  styles?: ConversationInputStyles;
  /** Extra class name(s) merged onto the root wrapper element. */
  className?: string;
  /** Files supplied by a page-level drag-and-drop handler to be added as attachments. */
  pendingDropFiles?: File[];
  /** Called after the inner `Input` has consumed `pendingDropFiles`, signalling the parent to clear its state. */
  onDropFilesConsumed?: () => void;
  /** Already-uploaded attachments supplied by the host and awaiting insertion into the local tray. */
  pendingAttachments?: Attachment[];
  /** Called after `pendingAttachments` have been inserted into the local tray. */
  onPendingAttachmentsConsumed?: () => void;
  /** Character count above which a pasted plain-text string is converted to an attachment rather than inserted inline. Defaults to `4000`. Pass `Infinity` to disable. */
  pasteTextThreshold?: number;
  /**
   * Maximum character count for the message text. Sending text at or above this
   * length triggers `onMessageTooLong` instead of being accepted, on every model.
   * Pasting text that long additionally triggers it when the paste-to-attachment
   * conversion is disabled (`isAttachmentsEnabled` or `isTextAttachmentsAllowed`
   * is `false`). Separate from `pasteTextThreshold`, which only decides when a
   * paste becomes an attachment. Defaults to `50000`.
   */
  maxMessageLength?: number;
  /**
   * List of deployment items to populate the model selector menu. When `undefined`, the selector is not rendered.
   * `iconUrl` on each item must already be a fully resolved URL usable in `<img src>`.
   */
  deployments?: DeploymentItem[];
  /** ID of the currently selected deployment. When `null` or `undefined` and `deployments` is defined, the send button is disabled. */
  selectedDeploymentId?: string | null;
  /** Called when the user selects a different deployment from the dropdown. Receives the selected item's `id`. */
  onDeploymentChange?: (id: string) => void;
  /** Labels shown inside the model selector dropdown for the trigger and various loading states. */
  modelSelectorLabels?: ModelSelectorLabels;
  /** Accessible label for the send button. */
  sendLabel?: string;
  /** Tooltip shown on hover over the send button. */
  sendTooltip?: string;
  /** Tooltip for an empty composer (no text, attachments, or inline-start slot). Defaults to sendTooltip. */
  emptyMessageTooltip?: string;
  /** Accessible label for the stop button. */
  stopLabel?: string;
  /** Accessible label for each attachment card's remove button. Defaults to `'Remove attachment'`. */
  removeLabel?: string;
  /** Accessible label for each attachment card's retry button (error state only). Defaults to `'Retry upload'`. */
  retryLabel?: string;
  /** Accessible label for each attachment card's in-progress upload progress bar. Defaults to `'Uploading'`. */
  uploadingLabel?: string;
  /** When `true`, blocks all text input, send, attach, and drop interactions. Starter/action buttons and the model selector remain usable. Defaults to `false`. */
  isInputDisabled?: boolean;
  /**
   * When `true`, the model selector renders in a disabled, non-interactive
   * state (dimmed, does not open) while still showing the current model.
   * Independent of `isInputDisabled`, which disables the rest of the
   * composer — typing and sending remain usable.
   */
  isModelSelectorDisabled?: boolean;
  /**
   * When `true`, disables the send action without removing or dimming the
   * send button itself. Independent of `isInputDisabled`. Defaults to `false`.
   */
  isSendDisabled?: boolean;
  /**
   * Extra class name(s) merged onto the inner `Input` wrapper element (the
   * bordered container around the textarea/model-selector/send-button row),
   * distinct from `className` which styles this component's own outer root.
   */
  inputClassName?: string;
  /**
   * When `true`, the mic button is rendered and voice recording is enabled.
   * The host app derives this from its recording/recognition capabilities.
   * When `false` or absent, the dictation button is hidden.
   */
  isAudioMessageSupported?: boolean;
  /** Enables Record voice in the add menu when attachments are enabled. Defaults to isAudioMessageSupported. */
  isVoiceRecordingSupported?: boolean;
  /** Label for the audio attachment recording menu item. Defaults to 'Record voice'. */
  recordVoiceLabel?: string;
  /** Host-owned recognition. When supplied, the microphone button inserts draft text; Record voice always attaches audio. */
  onTranscribeAudio?: TranscribeAudio;
  /** Status announced while recognizing speech. Defaults to 'Transcribing audio…'. */
  transcribingLabel?: string;
  /** Fallback recording/recognition error. Defaults to 'Voice input failed'. */
  voiceErrorLabel?: string;
  /** Accessible label for the mic button. Defaults to `'Dictate'`. */
  micLabel?: string;
  /** Accessible label for the stop-recording button inside the voice bar. Defaults to `'Stop recording'`. */
  stopRecordingLabel?: string;
  /** Accessible label for the discard / X button inside the voice bar. Defaults to `'Discard recording'`. */
  discardRecordingLabel?: string;
  /**
   * Controls which key combination submits the message.
   * - `SendOnEnter.Enter` (default): Enter submits; Shift+Enter inserts a newline.
   * - `SendOnEnter.MetaEnter`: ⌘+Enter (macOS) / Ctrl+Enter (Windows/Linux) submits; bare Enter inserts a newline.
   */
  sendOnEnter?: SendOnEnter;
  /**
   * When provided, a "Chat settings" item is added to the `+` menu.
   * Clicking it opens a modal with fields gated by `features`.
   */
  chatSettings?: ChatSettingsConfig;
  /** When `true`, focuses the textarea on mount. Defaults to `false`. */
  autoFocus?: boolean;
  /**
   * Ordered list of previously sent message strings for the current
   * conversation (oldest first, most-recent last). When provided, pressing
   * Up in the textarea recalls the previous entry; pressing Down returns
   * toward the current draft. Omit or pass an empty array to disable
   * keyboard history navigation.
   */
  messageHistory?: readonly string[];
  /** Called when user selects "DIAL file system" from the attach menu. When absent, the menu item is not rendered. */
  onDialFileSystemClick?: () => void;
  /** Label for the "DIAL file system" menu item. Defaults to `'DIAL file system'`. */
  dialFileSystemLabel?: string;
  /** Accessible label for the `+` trigger button. Defaults to `'Add'`. */
  addMenuTitle?: string;
  /**
   * Value applied verbatim as the `accept` attribute on the native device
   * file picker (`<input type="file">`), hinting the OS dialog to grey out or
   * hide unsupported file types. Resolved by the host from the selected
   * model's supported attachment types. When absent, every file type is
   * selectable. Forwarded to the inner `Input`.
   */
  fileAccept?: string;
  /**
   * Called synchronously for each attachment after it is added, before upload begins.
   * Return an `AttachmentErrorReason` to reject the attachment (it enters error state
   * and `onUploadAttachment` is NOT called). Return `undefined` to allow normal upload.
   */
  validateAttachment?: (
    attachment: Attachment,
  ) => AttachmentErrorReason | undefined;
  /**
   * When `false`, long pasted plain text is inserted inline instead of being
   * converted to a text attachment. Set to `false` when the selected model
   * does not support attachments. Forwarded to the inner `Input`.
   */
  isAttachmentsEnabled?: boolean;
  /**
   * When `false`, long pasted plain text is inserted inline instead of being
