export enum ActionRowLayout {
  /** Textarea occupies its own line; the add button, tool chips, and footer actions wrap below it. */
  Stacked = 'stacked',
  /** Add button, textarea, and footer actions share one line; tool chips move to their own row above. Ignored on mobile. */
  Inline = 'inline',
}

export enum SendOnEnter {
  /** Enter submits; Shift+Enter inserts a newline. */
  Enter = 'enter',
  /** ⌘+Enter (macOS) / Ctrl+Enter (Windows/Linux) submits; bare Enter inserts a newline. */
  MetaEnter = 'meta-enter',
}

export type TranscribeAudio = (
  file: File,
  signal: AbortSignal,
) => Promise<string>;

export interface ChatSettingsValues {
  /** Updated response format, present when the response-format field was shown. */
